package sv.edu.udb.pokebattle.controller;
import java.util.UUID; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import sv.edu.udb.pokebattle.dto.*; import sv.edu.udb.pokebattle.service.CombateService;
@RestController @RequestMapping("/api/partidas/{partidaId}") @RequiredArgsConstructor public class CombateController { private final CombateService service; @GetMapping("/estado") public EstadoPartidaResponse estado(@PathVariable UUID partidaId){return service.estado(partidaId);}@GetMapping("/turno") public TurnoActualResponse turno(@PathVariable UUID partidaId){return service.turno(partidaId);}@PostMapping("/acciones/atacar") public AccionCombateResponse atacar(@PathVariable UUID partidaId,@Valid @RequestBody AtacarRequest d){return service.atacar(partidaId,d);}@PostMapping("/acciones/cambiar-pokemon") public AccionCombateResponse cambiar(@PathVariable UUID partidaId,@Valid @RequestBody CambiarPokemonRequest d){return service.cambiar(partidaId,d);}@PostMapping("/acciones/rendirse") public AccionCombateResponse rendirse(@PathVariable UUID partidaId,@Valid @RequestBody RendirseRequest d){return service.rendirse(partidaId,d);} }
